template <size_t N>
static const char *find(const Pair (&t)[N], const char *key) {
  if (!key || !*key) return nullptr;
  for (size_t i = 0; i < N; i++)
    if (strcmp(t[i].k, key) == 0) return t[i].v;
  return nullptr;
}

// Binary search in a generated table: `codes` holds n sorted 3-character codes back to back.
static const char *dbFind(const char *codes, const char *const *names, int n, const char *key) {
  if (!key || strlen(key) != 3) return nullptr;
  int lo = 0, hi = n - 1;
  while (lo <= hi) {
    int mid = (lo + hi) / 2;
    int cmp = strncmp(codes + mid * 3, key, 3);
    if (cmp == 0) return names[mid];
    if (cmp < 0) lo = mid + 1; else hi = mid - 1;
  }
  return nullptr;
}

const char *airportCity(const char *iata) {
  if (const char *c = find(AIRPORTS, iata)) return c;
  return dbFind(AIRPORT_DB_CODES, AIRPORT_DB_CITY, AIRPORT_DB_SIZE, iata);
}

const char *aircraftName(const char *icaoType) { return find(AIRCRAFT, icaoType); }

static const char *dbAirline(const char *icao) {
  return dbFind(AIRLINE_ICAO_CODES, AIRLINE_ICAO_NAME, AIRLINE_ICAO_SIZE, icao);
}

// Order: hand-made IATA list (from the flight number) -> hand-made ICAO list -> full ICAO database,
// using the callsign prefix (KZR921 -> KZR; registration-style callsigns like UPEM012 are skipped),
// then the FR24 airline field.
const char *airlineName(const char *flightNo, const char *icao, const char *callsign) {
  if (flightNo && strlen(flightNo) >= 2) {
    char pre[3] = {flightNo[0], flightNo[1], 0};
    if (const char *n = find(AIRLINES_IATA, pre)) return n;
  }
  auto alpha = [](char c) { return isalpha((unsigned char)c) != 0; };
  char cs[4] = "";
  if (callsign && strlen(callsign) >= 4 && alpha(callsign[0]) && alpha(callsign[1]) &&
      alpha(callsign[2]) && isdigit((unsigned char)callsign[3])) {
    memcpy(cs, callsign, 3);
    cs[3] = 0;
  }
  if (const char *n = find(AIRLINES_ICAO, cs)) return n;
  if (const char *n = find(AIRLINES_ICAO, icao)) return n;
  if (const char *n = dbAirline(cs)) return n;
  return dbAirline(icao);
}
